update_md5_8d0903d5d984d5946b3d340dd73c0.find_text:
import { exec } from "child_process";
import { promisify } from "util";
import { EventEmitter } from "events";

const execAsync = promisify(exec);

update_md5_8d0903d5d984d5946b3d340dd73c0.content_md5_8d0903d5d984d5946b3d340dd73c:
import { execFile } from "child_process";
import { promisify } from "util";
import { EventEmitter } from "events";

const execFileAsync = promisify(execFile);

update_md5_2512d66ce55c01dd694de8115e65a.content_md5_2512d66ce55c01dd694de8115e65:
// On Windows, `which` is usually unavailable; `where` is the native equivalent.
await execFileAsync(
  isWindows ? "where" : "which",
  [cmd],
  isWindows ? { windowsHide: true } : undefined
);

update_md5_a4c33bdbdb193c2e1450707cf2523.content_md5_a4c33bdbdb193c2e1450707cf252:
await execFileAsync(
  cmd,
  [filename],
  isWindows ? { windowsHide: true } : undefined
);
